<problem_description>
A string a of length m is called antipalindromic iff m is even, and for each i (1 ≤ i ≤ m) ai ≠ am - i + 1.Ivan has a string s consisting of n lowercase Latin letters; n is even. He wants to form some string t that will be an antipalindromic permutation of s. Also Ivan has denoted the beauty of index i as bi, and the beauty of t as the sum of bi among all indices i such that si = ti.Help Ivan to determine maximum possible beauty of t he can get.
</problem_description>

Here is the Java 8 code you have to repair:
<original_code>
import java.io.*;
import java.util.*;

public class Educational {
    public static void main(String[] args) throws IOException {
        new Educational().run();
    }

    private void run() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim().split("\\s+")[0]);
        String s = br.readLine();
        int[] b = Arrays.stream(br.readLine().trim().split("\\s+")).mapToInt(Integer::parseInt).toArray();
        char[] res = s.toCharArray();

        List<Integer> waitingList = new ArrayList<>();
        for (int i = 0; i < n / 2; i++) {
            if (res[i] == res[getvisavis(n, i)]) {
                if (waitingList.isEmpty()) {
                    waitingList.add(i);
                } else {
                    boolean swapped = false;
                    for (int j : waitingList) {
                        if (res[j] != res[i]) {
                            int idx1 = b[j] < b[getvisavis(n, j)] ? j : getvisavis(n, j);
                            int idx2 = b[i] < b[getvisavis(n, i)] ? i : getvisavis(n, i);
                            swap(res, idx1, idx2);
                            b[idx1] = 0;
                            b[idx2] = 0;
                            waitingList.remove(Integer.valueOf(j));
                            swapped = true;
                            break;
                        }
                    }
                    if (!swapped) waitingList.add(i);
                }
            }
        }

        Map<Integer, Set<Integer>> w = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            w.computeIfAbsent(b[i], k -> new HashSet<>()).add(i);
        }

        for (int i = 0; i < n / 2; i++) {
            if (res[i] == res[getvisavis(n, i)]) {
                int idxToChange = b[i] < b[getvisavis(n, i)] ? i : getvisavis(n, i);
                boolean done = false;
                for (Map.Entry<Integer, Set<Integer>> entry : w.entrySet()) {
                    for (int j : entry.getValue()) {
                        if (j == i || j == idxToChange || res[idxToChange] == res[j] || res[idxToChange] == res[getvisavis(n, j)]) continue;
                        swap(res, idxToChange, j);
                        b[j] = 0;
                        b[idxToChange] = 0;
                        w.get(0).add(j);
                        w.get(0).add(idxToChange);
                        done = true;
                        break;
                    }
                    if (done) break;
                }
                if (res[i] == res[getvisavis(n, i)]) System.out.println("alarma");
            }
        }

        for (int i = 0; i < n / 2; i++) {
            if (res[i] == res[getvisavis(n, i)]) System.out.println("FFFF");
        }

        int sum = 0;
        for (int val : b) sum += val;
        System.out.println(sum);
    }

    private static int getvisavis(int n, int i) {
        return n - i - 1;
    }

    private static void swap(char[] a, int i, int j) {
        char temp = a[i];
        a[i] = a[j];
        a[j] = temp;
    }
}
